// src/components/dashboard/DashboardLayoutClient.tsx
'use client';

import React from 'react'; // Or { ReactNode } if only that's needed directly
import type { Tenant } from '@prisma/client'; // Assuming Tenant is passed as a prop

// Import general dashboard types from the correct central types file
import type {
  NavItem,
  DashboardCard,
  Notification,
  RenderMainContentParams,
  // BaseDashboardLayoutProps, // Only if you extend it for specific props
} from './types';

// Import BaseDashboardLayout component
import BaseDashboardLayout from './BaseDashboardLayout';

// Import QuickBoard specific types from their correct location
import type {
  QuickBoardPlugin,
  BasePluginComponentProps, // If directly used here, or if QuickBoardPlugin generic needs it
} from './quickboard/types';

// Import icons (example)
import {
  LayoutDashboard,
  Users,
  Settings,
  BarChart3,
  MessageSquare,
  Briefcase,
  Layers, // For QuickBoard example
} from 'lucide-react';

// Import QuickBoardComponent (assuming its location)
import QuickBoardComponent from './quickboard/QuickBoardComponent'; // Adjust path if needed

// Example Plugins (these would typically be defined elsewhere and imported)
// For demonstration, defining inline structures that match QuickBoardPlugin
const exampleUserCountPlugin: QuickBoardPlugin = {
  id: 'user-count',
  title: 'Active Users',
  component: ({ showCustomModal }) => ( // Example of a simple plugin component
    <div className="p-4 bg-blue-100 rounded-lg shadow">
      <h3 className="font-semibold text-blue-700">Active Users Today</h3>
      <p className="text-2xl font-bold">125</p>
      <button
        className="text-sm text-blue-600 hover:underline mt-2"
        onClick={() => showCustomModal && showCustomModal(<div>Detailed user analytics...</div>, "User Details")}
      >
        View Details
      </button>
    </div>
  ),
  roles: ['admin', 'manager'], // Example roles
};

const exampleSalesChartPlugin: QuickBoardPlugin = {
  id: 'sales-chart',
  title: 'Sales Overview',
  component: () => (
    <div className="p-4 bg-green-100 rounded-lg shadow">
      <h3 className="font-semibold text-green-700">Monthly Sales</h3>
      <div className="h-32 bg-green-200 flex items-center justify-center text-green-600 rounded mt-2">
        [Sales Chart Placeholder]
      </div>
    </div>
  ),
  roles: ['admin', 'sales_manager'],
};


// Props specific to DashboardLayoutClient
interface DashboardLayoutClientProps {
  tenant: Tenant;
  // You might pass other specific initial props for this client layout
  // initialActiveSectionProp?: string;
  // initialNotificationsProp?: Notification[];
}

export default function DashboardLayoutClient({
  tenant,
  // initialActiveSectionProp,
  // initialNotificationsProp,
}: DashboardLayoutClientProps) {
  // Define navigation items specific to the Client dashboard
  const navItems: NavItem[] = [
    { icon: <LayoutDashboard size={20} />, title: 'Dashboard' },
    { icon: <Layers size={20} />, title: 'QuickBoard' }, // Added QuickBoard nav item
    { icon: <Users size={20} />, title: 'Team Members' },
    { icon: <BarChart3 size={20} />, title: 'Analytics' },
    { icon: <MessageSquare size={20} />, title: 'Messages' },
    { icon: <Briefcase size={20} />, title: 'Projects' },
    { icon: <Settings size={20} />, title: 'Settings' },
    // Add a Notifications item if you want a dedicated page for it
    { icon: <Settings size={20} />, title: 'Notifications' }, // Example, ensure this matches view all logic
  ];

  // Define dashboard cards specific to the Client dashboard (optional)
  const dashboardCards: DashboardCard[] = [
    { id: 'clientCard1', title: 'Active Projects Summary' },
    { id: 'clientCard2', title: 'Team Performance Metrices' },
    { id: 'clientCard3', title: 'Recent Client Activities' },
  ];

  // Example initial notifications (could also be fetched or passed as props)
  const initialNotifications: Notification[] = [
    { id: 1, text: 'New project "Alpha" has been assigned to your team.', read: false, timestamp: '2 hours ago' },
    { id: 2, text: 'Review for "Task Omega" is due tomorrow.', read: true, timestamp: 'Yesterday' },
  ];

  // Example QuickBoard plugins for this client layout
  const clientQuickBoardPlugins: QuickBoardPlugin<BasePluginComponentProps>[] = [
    exampleUserCountPlugin,
    exampleSalesChartPlugin,
    // Add more plugins relevant to the client dashboard
  ];

  // Custom renderMainContent function for the Client dashboard
  const renderMainContent = (params: RenderMainContentParams): React.ReactNode => {
    const { activeSection, showCustomModal, tenant: currentTenant } = params; // Destructure all needed props

    // Handle QuickBoard section
    if (activeSection === 'QuickBoard') {
      return (
        <QuickBoardComponent
          plugins={clientQuickBoardPlugins} // Pass the defined plugins
          showCustomModal={showCustomModal} // Pass down the modal function
          // Potentially pass other context like tenantId if QuickBoardComponent or plugins need it
          // tenantId={currentTenant.id}
        />
      );
    }

    if (activeSection === 'Dashboard') {
      return (
        <div>
          <h2 className="text-2xl font-semibold mb-4">Client Dashboard for {currentTenant.name}</h2>
          <p>This is the main dashboard content area. You can render specific widgets or summaries here.</p>
          <div className="mt-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {dashboardCards.map(card => (
              <div key={card.id} className="bg-white p-4 rounded-lg shadow">
                <h3 className="font-semibold">{card.title}</h3>
                <p className="text-sm text-gray-600">Details for {card.title}...</p>
              </div>
            ))}
          </div>
        </div>
      );
    }

    if (activeSection === 'Notifications') {
        return (
            <div>
                <h2 className="text-2xl font-semibold mb-4">All Notifications</h2>
                {/* Render a list of all notifications, perhaps with more details */}
                <ul>
                    {initialNotifications.map(n => <li key={n.id} className={`p-2 ${!n.read ? 'font-bold' : ''}`}>{n.text} ({n.timestamp})</li>)}
                </ul>
            </div>
        );
    }


    // Fallback or other sections
    return (
      <div>
        <h2 className="text-xl font-semibold">Content for: {activeSection}</h2>
        <p>Details for {activeSection} will be shown here.</p>
        <button
            className="mt-4 px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600"
            onClick={() => showCustomModal(<div>Modal content for {activeSection}</div>, `Details: ${activeSection}`)}
        >
            Show Modal for {activeSection}
        </button>
      </div>
    );
  };

  return (
    <BaseDashboardLayout
      tenant={tenant}
      tenantType="client" // Explicitly set tenantType for localStorage keys, etc.
      navItems={navItems}
      dashboardCards={dashboardCards} // Pass the cards if BaseDashboardLayout uses them directly for something
      initialActiveSection={'Dashboard'} // Or use initialActiveSectionProp
      initialNotifications={initialNotifications} // Or use initialNotificationsProp
      renderMainContent={renderMainContent} // Provide the custom renderer
      // headerRightContent={<div>Client Specific Header Info</div>} // Optional
      // sidebarFooterContent={<div>Client Footer</div>} // Optional
    />
  );
}